#include <zephyr/device.h>
#include <zephyr/devicetree.h>
#include <zephyr/kernel.h>

#include <ztest/ztest.h>

/* This is the same as `DEVICE_DT_GET(DT_NODELABEL(test_##lower))` */
#define DEV_HDL(upper)
	COND_CODE_1(DT_NODE_HAS_STATUS(DT_NODELABEL(test_##lower), okay),
		    (DEVICE_DT_GET(DT_NODELABEL(test_##lower))), (NULL))

/* This is the same as `DEVICE_DT_GET_OR_NULL(DT_NODELABEL(test_##lower))` */
#define DEV_HDL_OR_NULL(upper) DEVICE_DT_GET_OR_NULL(DT_NODELABEL(test_##lower))

#define lower i2c
static const struct device *const TEST_I2C = DEV_HDL(I2C);
#undef lower

#define lower spi
static const struct device *const TEST_SPI = DEV_HDL(SPI);
#undef lower

#define lower uart
static const struct device *const TEST_UART = DEV_HDL(UART);
#undef lower

#define lower disabled
static const struct device *const TEST_DISABLED = DEV_HDL(DISABLED);
#undef lower

static const struct device *init_order[3];
static size_t init_order_idx;

static int test_dev_init(const struct device *dev)
{
	if (init_order_idx < ARRAY_SIZE(init_order)) {
		init_order[init_order_idx++] = dev;
	}

	return 0;
}

/*
 * We can't use `DEVICE_DT_DEFINE` because that would require a Kconfig option to be enabled for
 * each `test-dev` compatible. Instead, we can use `DEVICE_DEFINE` and create the device from a
 * devicetree node.
 */
#define TEST_DEV_DEFINE(node_id)
	DEVICE_DEFINE(Z_DEVICE_DT_DEV_NAME_GET(node_id), test_dev_init, NULL, NULL, NULL,
		      POST_KERNEL, DT_PROP(node_id, init_priority), NULL)

DT_FOREACH_STATUS_OKAY(test_dev, TEST_DEV_DEFINE)

ZTEST(devicetree_devices, test_get_or_null)
{
	zassert_true(device_is_ready(TEST_I2C));
	zassert_true(device_is_ready(TEST_SPI));
	zassert_true(device_is_ready(TEST_UART));
	zassert_is_null(TEST_DISABLED);

	zassert_equal(TEST_I2C, DEV_HDL_OR_NULL(I2C));
	zassert_equal(TEST_SPI, DEV_HDL_OR_NULL(SPI));
	zassert_equal(TEST_UART, DEV_HDL_OR_NULL(UART));
	zassert_equal(TEST_DISABLED, DEV_HDL_OR_NULL(DISABLED));
}

ZTEST(devicetree_devices, test_init_get)
{
	const struct device *i2c = device_get_binding("TEST_I2C");
	const struct device *spi = device_get_binding("TEST_SPI");
	const struct device *uart = device_get_binding("TEST_UART");
	const struct device *disabled = device_get_binding("TEST_DISABLED");

	zassert_true(device_is_ready(i2c));
	zassert_true(device_is_ready(spi));
	zassert_true(device_is_ready(uart));
	zassert_is_null(disabled);

	zassert_equal(i2c, TEST_I2C);
	zassert_equal(spi, TEST_SPI);
	zassert_equal(uart, TEST_UART);
}

ZTEST(devicetree_devices, test_init_order)
{
	zassert_equal(init_order_idx, 3);
	zassert_equal(init_order[0], TEST_SPI, "init_order[0] not equal to TEST_SPI");
	zassert_equal(init_order[1], TEST_UART, "init_order[1] not equal to TEST_UART");
	zassert_equal(init_order[2], TEST_I2C, "init_order[2] not equal to TEST_I2C");
}

ZTEST_SUITE(devicetree_devices, NULL, NULL, NULL, NULL, NULL);
